var rm=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var a2=root.querySelector('.t213-vwap-band-a2'),a1=root.querySelector('.t213-vwap-band-a1');
var vwP=root.querySelector('.t213-vwap-band-vw'),pxP=root.querySelector('.t213-vwap-band-px');
var mk=root.querySelector('.t213-vwap-band-mk'),sig=root.querySelector('.t213-vwap-band-sig');
var badge=root.querySelector('.t213-vwap-band-badge'),lastEl=root.querySelector('.t213-vwap-band-last');
var N=46,pr=[],p=231.10,i;
for(i=0;i<N;i++){p+=(Math.random()-.48)*.22;pr.push(p);}
function X(k){return 3+k/(N-1)*294;}
function render(){
  var vw=[],s=0,u1=[],d1=[],u2=[],d2=[],sd=[],lo=1e9,hi=-1e9;
  for(i=0;i<N;i++){s+=pr[i];vw.push(s/(i+1));}
  for(i=0;i<N;i++){var w=pr.slice(Math.max(0,i-11),i+1),m=vw[i],v=0;
    w.forEach(function(x){v+=(x-m)*(x-m);});
    var sg=Math.sqrt(v/w.length)||.05;sd.push(sg);
    u1.push(m+sg);d1.push(m-sg);u2.push(m+2*sg);d2.push(m-2*sg);
    lo=Math.min(lo,m-2*sg,pr[i]);hi=Math.max(hi,m+2*sg,pr[i]);}
  var Y=function(v){return 5+(hi-v)/(hi-lo||1)*74;};
  function line(arr){var d='';for(i=0;i<N;i++)d+=(i?'L':'M')+X(i).toFixed(1)+' '+Y(arr[i]).toFixed(1);return d;}
  function area(up,dn){var d=line(up);for(i=N-1;i>=0;i--)d+='L'+X(i).toFixed(1)+' '+Y(dn[i]).toFixed(1);return d+'Z';}
  a2.setAttribute('d',area(u2,d2));a1.setAttribute('d',area(u1,d1));
  vwP.setAttribute('d',line(vw));pxP.setAttribute('d',line(pr));
  var lx=X(N-1),ly=Y(pr[N-1]);
  mk.style.transform='translate('+lx.toFixed(1)+'px,'+ly.toFixed(1)+'px)';
  var z=(pr[N-1]-vw[N-1])/sd[N-1];
  sig.textContent=(z>=0?'+':'−')+Math.abs(z).toFixed(2)+'σ';
  badge.firstChild.nodeValue=(z>=0?'▲ ':'▼ ');
  badge.style.color=z>=0?'#22D48A':'#FF5A6E';
  lastEl.textContent=pr[N-1].toFixed(2);
  root.querySelector('.t213-vwap-band-t--v').textContent='— vwap '+vw[N-1].toFixed(2);
}
render();
if(rm)return;
setInterval(function(){pr.shift();pr.push(pr[pr.length-1]+(Math.random()-.47)*.24);render();},900);

var rm=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var wrap=root.querySelector('.t213-cum-delta-bars'),poly=root.querySelector('.t213-cum-delta-line');
var val=root.querySelector('.t213-cum-delta-v'),arw=root.querySelector('.t213-cum-delta-a');
var N=28,d=[],ups=[],dns=[],prev=0,i;
for(i=0;i<N;i++)d.push(Math.round((Math.random()-.44)*380));
for(i=0;i<N;i++){var col=document.createElement('div');col.className='t213-cum-delta-col';
  var u=document.createElement('div');u.className='t213-cum-delta-up';
  var uf=document.createElement('i');uf.className='t213-cum-delta-f';if(!rm)uf.style.transitionDelay=(i*16)+'ms';u.appendChild(uf);
  var n=document.createElement('div');n.className='t213-cum-delta-dn';
  var nf=document.createElement('i');nf.className='t213-cum-delta-f';if(!rm)nf.style.transitionDelay=(i*16)+'ms';n.appendChild(nf);
  col.appendChild(u);col.appendChild(n);wrap.appendChild(col);ups.push(uf);dns.push(nf);}
function count(to){var from=prev,t0=performance.now();prev=to;
  if(rm){val.textContent=(to>=0?'+':'−')+Math.abs(to).toLocaleString('en-US');return;}
  function s(t){var k=Math.min(1,(t-t0)/500),e=1-Math.pow(1-k,3),v=Math.round(from+(to-from)*e);
    val.textContent=(v>=0?'+':'−')+Math.abs(v).toLocaleString('en-US');if(k<1)requestAnimationFrame(s);}
  requestAnimationFrame(s);}
function paint(){
  var mx=1;d.forEach(function(x){mx=Math.max(mx,Math.abs(x));});
  d.forEach(function(x,k){var h=(Math.abs(x)/mx*100).toFixed(1)+'%';
    ups[k].style.height=x>0?h:'0%';dns[k].style.height=x<0?h:'0%';});
  var c=0,cs=[],lo=1e9,hi=-1e9;
  d.forEach(function(x){c+=x;cs.push(c);lo=Math.min(lo,c);hi=Math.max(hi,c);});
  if(hi-lo<1)hi=lo+1;
  var pts=cs.map(function(v,k){return (k/(N-1)*100).toFixed(2)+','+(6+(hi-v)/(hi-lo)*88).toFixed(2);}).join(' ');
  poly.setAttribute('points',pts);
  count(c);
  var up=c>=0;val.style.color=up?'#22D48A':'#FF5A6E';arw.style.color=up?'#22D48A':'#FF5A6E';
  arw.textContent=up?'▲':'▼';
}
if(rm){paint();return;}
ups.forEach(function(u){u.style.height='0%';});
requestAnimationFrame(function(){requestAnimationFrame(paint);});
setInterval(function(){d.shift();d.push(Math.round((Math.random()-.44)*400));
  ups.forEach(function(u,k){u.style.transitionDelay='0ms';dns[k].style.transitionDelay='0ms';});paint();},1150);

