var rm=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var feed=root.querySelector('.t213-block-tape-feed'),btn=root.querySelector('.t213-block-tape-btn');
var cn=root.querySelector('.t213-block-tape-cn'),sn=root.querySelector('.t213-block-tape-sn');
var steps=[250,500,1000],si=0,thr=250,px=584.12,blocks=0,shares=0,vns=['ARCA','EDGX','BATS','NSDQ','IEX'],i;
function clock(){var d=new Date();return ('0'+d.getHours()).slice(-2)+':'+('0'+d.getMinutes()).slice(-2)+':'+('0'+d.getSeconds()).slice(-2);}
function mark(r){var big=+r.getAttribute('data-sz')>=thr;r.classList.toggle('t213-block-tape-row--block',big);}
function add(){
  var sz=Math.random()<.22?(260+Math.random()*3400)|0:(30+Math.random()*380)|0;
  var buy=Math.random()>.47;
  px=+(px+(Math.random()-.5)*.09).toFixed(2);
  var r=document.createElement('div');
  r.className='t213-block-tape-row '+(buy?'t213-block-tape-row--buy':'t213-block-tape-row--sell');
  r.setAttribute('data-sz',sz);
  r.innerHTML='<span class="t213-block-tape-tm">'+clock()+'</span>'+
    '<span class="t213-block-tape-sz">'+sz.toLocaleString('en-US')+'</span>'+
    '<span class="t213-block-tape-at">'+(buy?'▲':'▼')+' '+px.toFixed(2)+'</span>'+
    '<span class="t213-block-tape-fl">BLOCK</span>'+
    '<span class="t213-block-tape-vn">'+vns[(Math.random()*vns.length)|0]+'</span>';
  mark(r);
  feed.insertBefore(r,feed.firstChild);
  while(feed.children.length>3)feed.removeChild(feed.lastChild);
  if(sz>=thr){blocks++;shares+=sz;cn.textContent=blocks.toLocaleString('en-US');
    sn.textContent=shares>=1000?(shares/1000).toFixed(1)+'K':shares.toLocaleString('en-US');}
}
for(i=0;i<3;i++)add();
btn.addEventListener('click',function(){si=(si+1)%steps.length;thr=steps[si];
  btn.innerHTML='&ge; '+thr.toLocaleString('en-US');
  [].slice.call(feed.children).forEach(mark);});
if(rm)return;
setInterval(add,1250);
